select case when location in ('Singapore', 'New York') then 'core' else 'other' end as location_group, sum(budget) as total_budget, count(*) as cnt, sum(sum(budget)) over (order by case when location in ('Singapore', 'New York') then 'core' else 'other' end) as cumulative_budget from departments group by case when location in ('Singapore', 'New York') then 'core' else 'other' end order by location_group, cnt desc
